    <script>
        // Theme Management
        const themeToggle = document.getElementById('themetoggle');
        const lightIcon = document.getElementById('themeiconlight');
        const darkIcon = document.getElementById('themeicondark');
        const htmlEl = document.documentElement;

        function applyTheme(theme) {
            htmlEl.setAttribute('datatheme', theme);
            if (theme === 'dark') {
                lightIcon.classList.add('hidden');
                darkIcon.classList.remove('hidden');
            } else {
                lightIcon.classList.remove('hidden');
                darkIcon.classList.add('hidden');
            }
        }

        const savedTheme = localStorage.getItem('theme') || (window.matchMedia('(preferscolorscheme: dark)').matches ? 'dark' : 'light');
        applyTheme(savedTheme);

        themeToggle.addEventListener('click', () => {
            const currentTheme = htmlEl.getAttribute('datatheme') || (window.matchMedia('(preferscolorscheme: dark)').matches ? 'dark' : 'light');
            const newTheme = currentTheme === 'light' ? 'dark' : 'light';

            applyTheme(newTheme);
            localStorage.setItem('theme', newTheme);
        });

        // Auto theme detection
        window.matchMedia('(preferscolorscheme: dark)').addEventListener('change', e => {
            if (!localStorage.getItem('theme')) {
                applyTheme(e.matches ? 'dark' : 'light');
            }
        });

        // API Integration
        const analyzeBtn = document.getElementById('analyzebtn');
        const payloadInput = document.getElementById('payloadinput');
        const resultsDiv = document.getElementById('analysisresults');

        analyzeBtn.addEventListener('click', async () => {
            const payload = payloadInput.value.trim();
            if (!payload) {
                alert('Please enter a payload to analyze');
                return;
            }

            analyzeBtn.textContent = '🔄 Analyzing with all engines...';
            analyzeBtn.disabled = true;

            try {
                const response = await fetch('/api/analyze', {
                    method: 'POST',
                    headers: {
                        'ContentType': 'application/json',
                    },
                    body: JSON.stringify({ payload })
                });

                const result = await response.json();
                displayResults(result);
                addToSecurityLogs(result);
                updateMetrics();

            } catch (error) {
                console.error('Analysis failed:', error);
                alert('Analysis failed. Please try again.');
            } finally {
                analyzeBtn.textContent = '🚀 MultiEngine Analysis';
                analyzeBtn.disabled = false;
            }
        });

        function displayResults(result) {
            const threatLevelClass = getThreatLevelClass(result.threat_level);
            const threatLevelText = getThreatLevelText(result.threat_level);

            resultsDiv.innerHTML = 
                <div class="glasscard p4 ${threatLevelClass} ${result.threat_level > 70 ? 'criticalpulse' : ''}">
                    <div class="grid md:gridcols2 gap4 mb4">
                        <div>
                            <h4 class="fontbold textlg mb2">🎯 Analysis Results</h4>
                            <div class="spacey2 textsm">
                                <div><strong>Threat Level:</strong> ${threatLevelText} (${result.threat_level}%)</div>
                                <div><strong>Threat Type:</strong> ${result.threat_type}</div>
                                <div><strong>Confidence:</strong> ${(result.confidence  100).toFixed(1)}%</div>
                                <div><strong>Processing Time:</strong> ${result.processing_time}ms</div>
                            </div>
                        </div>
                        <div>
                            <h4 class="fontbold textlg mb2">🔬 Consensus Analysis</h4>
                            <div class="spacey2 textsm">
                                <div><strong>Byzantine Nodes:</strong> ${result.consensus_result.participating_nodes}</div>
                                <div><strong>Quantum Entanglement:</strong> ${(result.consensus_result.quantum_entanglement  100).toFixed(1)}%</div>
                                <div><strong>Final Score:</strong> ${result.consensus_result.final_score}%</div>
                                <div><strong>Consensus:</strong> ${result.consensus_result.consensus_reached ? 'Reached' : 'Pending'}</div>
                            </div>
                        </div>
                    </div>

                    <div class="grid md:gridcols4 gap4 mt4">
                        <div class="glasscard p3">
                            <h5 class="fontbold textsm mb1">🧠 OCaml Neural</h5>
                            <div class="textxs">Confidence: ${(result.engine_results.ocaml_neural.confidence  100).toFixed(1)}%</div>
                        </div>
                        <div class="glasscard p3">
                            <h5 class="fontbold textsm mb1">⚡ Zig Performance</h5>
                            <div class="textxs">Time: ${(result.engine_results.zig_performance.processing_time_ns / 1000).toFixed(0)}μs</div>
                        </div>
                        <div class="glasscard p3">
                            <h5 class="fontbold textsm mb1">🔒 Coq Verified</h5>
                            <div class="textxs">Status: ${result.engine_results.coq_verification.theorem_proof_status}</div>
                        </div>
                        <div class="glasscard p3">
                            <h5 class="fontbold textsm mb1">🌐 Erlang Distributed</h5>
                            <div class="textxs">Coherence: ${result.engine_results.erlang_distributed.quantum_coherence}%</div>
                        </div>
                    </div>
