        function getThreatLevelClass(level) {
            if (level >= 80) return 'threatcritical';
            if (level >= 60) return 'threathigh';
            if (level >= 30) return 'threatmedium';
            return 'threatlow';
        }

        function getThreatLevelText(level) {
            if (level >= 80) return 'CRITICAL';
            if (level >= 60) return 'HIGH';
            if (level >= 30) return 'MEDIUM';
            return 'LOW';
        }

        function addToSecurityLogs(result) {
            const logs = document.getElementById('securitylogs');
            const timestamp = new Date().toLocaleTimeString();
            const threatClass = result.threat_level >= 60 ? 'textred400' : 
                               result.threat_level >= 30 ? 'textyellow400' : 'textgreen400';

            const logEntry = document.createElement('div');
            logEntry.className = threatClass;
            logEntry.textContent = [${timestamp}] ${result.threat_type} detected - Level: ${result.threat_level}% - ID: ${result.id.substring(0, 8)};

            logs.appendChild(logEntry);
            logs.scrollTop = logs.scrollHeight;

            while (logs.children.length > 25) {
                logs.removeChild(logs.children[3]);
            }
        }

        // Realtime updates
