                const metrics = await metricsResponse.json();
                const engines = await enginesResponse.json();

                updateLanguageGrid(engines);
                updateSystemMetrics(status.security_metrics);
                updateThreatStats(status.security_metrics);
                updateEngineStatus(status.engines);
                updateQuantumStatus(status.quantum_status);

