            const icons = {
                'OCaml': '🧠', 'Zig': '⚡', 'Coq': '🔒', 'Erlang': '🌐',
                'Haskell': '🔐', 'Lean4': '🎯', 'Idris2': '📊', 'Koka': '🔄'
            };
            return icons[language] || '⚙️';
        }

