                        <span class="textsm fontbold textpurple400">${(metrics.consensus_rate  100).toFixed(1)}%</span>
                    </div>
                    <div class="metricbar">
                        <div class="metricfill bgpurple400" style="width: ${metrics.consensus_rate  100}%"></div>
                    </div>
                </div>
            ;
        }

        function updateThreatStats(metrics) {
            const container = document.getElementById('threatstats');
            container.innerHTML = 
                <div class="textcenter">
                    <div class="text2xl fontbold textblue400">${metrics.threats_analyzed.toLocaleString()}</div>
                    <div class="textxs" style="color: var(textsecondary);">Analyzed</div>
                </div>
                <div class="textcenter">
                    <div class="text2xl fontbold textred400">${metrics.threats_blocked}</div>
                    <div class="textxs" style="color: var(textsecondary);">Blocked</div>
                </div>
                <div class="textcenter">
                    <div class="text2xl fontbold textyellow400">${metrics.false_positives}</div>
                    <div class="textxs" style="color: var(textsecondary);">False Pos.</div>
                </div>
                <div class="textcenter">
                    <div class="text2xl fontbold textgreen400">${metrics.uptime_percentage}%</div>
                    <div class="textxs" style="color: var(textsecondary);">Uptime</div>
                </div>
            ;
        }

        function updateEngineStatus(engines) {
            const container = document.getElementById('enginestatus');
            container.innerHTML = Object.entries(engines).map(([name, engine]) => 
                <div class="enginestatus">
                    <span>${name.replace('_', ' ').toUpperCase()}</span>
                    <div class="flex itemscenter spacex2">
                        <span class="textgreen400 textxs">${engine.status}</span>
                        <div class="statusindicator"></div>
                    </div>
                </div>
            ).join('');
        }

        function updateQuantumStatus(quantum) {
            const container = document.getElementById('quantumstatus');
            container.innerHTML = 
                <div class="flex justifybetween">
                    <span class="textsm">Entanglement Pairs</span>
                    <span class="textsm fontbold textcyan400">${quantum.entanglement_pairs}</span>
                </div>
                <div class="flex justifybetween">
                    <span class="textsm">Coherence Level</span>
                    <span class="textsm fontbold textgreen400">${quantum.coherence_level.toFixed(1)}%</span>
                </div>
                <div class="flex justifybetween">
                    <span class="textsm">Decoherence Time</span>
                    <span class="textsm fontbold textblue400">${quantum.decoherence_time}</span>
